G2 = [
dict(id='PD3B-016', order=1, topic='前提（假设）', key='GD2019X-48', ans_page=8,
 stem='在发达国家的产业结构中，服务业占了很高的比重。根据他们的经验，提高服务业占比就可以促进就业。但是，服务业具有较高的进入壁垒，这也是我国服务业发展相对滞后的一个重要原因。因此，我国可以通过打破服务业的行业壁垒进一步促进就业。\n以下最可能是上述论证潜在假设的是（　）。',
 options={'A': '服务业促进就业的规律适用于我国', 'B': '我国创造就业的能力弱于发达国家', 'C': '发达国家的服务业也存在行业壁垒', 'D': '其他行业对促进就业没有显著作用'},
 src='A', chk='A', diff='M',
 sol='论点：我国可以通过打破服务业行业壁垒进一步促进就业。论据：①发达国家经验：提高服务业占比可以促进就业；②进入壁垒高是我国服务业滞后的重要原因。缺口：论证链为“打破壁垒→服务业发展→促进就业”，后一环借自发达国家，须假设这一规律在我国同样成立。\nA：服务业促进就业的规律适用于我国——补上“外国经验→我国”这一环，否定它论证即落空，当选。\nB：我国创造就业能力弱于发达国家——与能否经由服务业促进就业无关。\nC：发达国家服务业也有壁垒——讲发达国家的壁垒，不影响我国打破壁垒的效果。\nD：其他行业对促进就业没有显著作用——论证无须排除其他行业，过强且不必要。\n提速：论据中出现“根据他国/他人经验”时，前提先想“经验能否移植”。',
 val='论据借用发达国家经验，前提是“规律适用于我国”，练经验移植型前提并排除“其他行业无作用”这类过强项。',
 flags=['扫描件解析出图核对'],
 notes='解析原文（扫描件第8页）：“A项：说明在我国服务业是可以促进就业的……是论证成立的假设，当选”；B、C、D均为话题不一致。与编者一致。同题见GD2019Z-43（乡镇卷，已一并锁定）。编者难度估计：中。'),

dict(id='PD3B-017', order=2, topic='解释', key='GD2023X-67',
 stem='小王经营着一家打印店，他发现，店内员工都很忙，大部分精力都花在了文件排版上。为了节省人力，他给店里的电脑安装了能自动完成常规排版操作的新款软件。然而，软件安装几个月后，店内员工反而更忙了。\n以下选项如果为真，最能解释这一现象的是（　）。',
 options={'A': '部分文档有特殊的排版要求，依然需要人工操作完成', 'B': '能自动排版文档后，该店的文印装订等业务量也因此大涨', 'C': '新软件操作有一定难度，员工需要接受培训才能熟练掌握', 'D': '安装软件后，该店并没有相应地调整排版和打印的收费标准'},
 src='B', chk='B', diff='M',
 sol='矛盾：安装能自动完成常规排版的软件（为节省人力）后，员工几个月后反而更忙。需要：一个使总工作量上升、且与装软件相连的因素。\nA：部分文档仍需人工排版——只说明软件不能包揽全部，最多“省得少”，解释不了“更忙”。\nB：能自动排版后，文印装订等业务量随之大涨——效率提高带来更多生意，总工作量上升，与装软件直接相连，当选。\nC：新软件要培训才能熟练——培训是短期负担，且只说“有一定难度”，解释不了几个月后仍更忙，力度弱。\nD：没有调整收费标准——收费与员工忙不忙无关。\n提速：“效率提高反而更忙”先找“效率→业务量增加”的链条。',
 val='效率提升反而更忙：练“效率→业务量增加”的解释链，与只能解释“省得少”的A、短期负担C区分。',
 flags=[],
 notes='解析原文（第23页“第67题 正确答案是：【B】”）：A“只能说明有些工作离不开人工操作”，C“只能说明使用前需要培训”。与编者一致。版本：xingce 同卷标“网友回忆版（县级卷）”，与本版逐字一致（标点除外）。编者难度估计：中。'),

dict(id='PD3B-018', order=3, topic='前提', key='GK2020D-103',
 stem='澳大利亚箱形水母是世界上毒性最强的动物之一，蜇人后其毒素会使人皮肤坏死并伴随剧痛，还会侵入人的心脏，使人在短时间内因心脏停搏而死亡。一只箱形水母体内携带的毒液足以致60人死亡，目前还没有针对其毒液的特效药物。近日，研究人员通过全基因组筛查的方法发现，人体细胞内一种名为ATP2B1的蛋白质是箱形水母毒液发挥毒性的必要条件，研究人员据此认为，通过靶向治疗方法降低胆固醇可以对抗箱形水母的毒液。\n以下哪项可以作为上述论证的前提？',
 options={'A': '靶向治疗方法是一种安全可靠的方法', 'B': 'ATP2B1蛋白质发挥作用需要胆固醇', 'C': '降低胆固醇后不会对人体产生副作用', 'D': '已研制出降低胆固醇的靶向治疗药物'},
 src='B', chk='B', diff='M',
 sol='论点：通过靶向治疗降低胆固醇可以对抗箱形水母毒液。论据：人体细胞内的ATP2B1蛋白质是毒液发挥毒性的必要条件。缺口：论据讲ATP2B1，论点讲降胆固醇，二者之间没有联系——必须假设胆固醇关系到ATP2B1发挥作用。\nA：靶向治疗安全可靠——讲安全性，不涉及降胆固醇能否对抗毒液，不是论证所需。\nB：ATP2B1发挥作用需要胆固醇——降胆固醇→ATP2B1无法发挥作用→毒液失去必要条件，链条接通，当选。\nC：降胆固醇后无副作用——讲副作用，与“能否对抗毒液”无关。\nD：已研制出相应靶向药物——讲现实条件，论点只说方法上“可以对抗”，不需要。\n提速：论点、论据各有一个对方没有的名词时，前提就是连接这两个名词的那句话。',
 val='论据讲ATP2B1、论点讲降胆固醇，练在两个新概念间搭桥的必要前提，排除安全性、副作用、药物已研制等非必要项。',
 flags=[],
 notes='解析原文（第21页）：B“在‘胆固醇’与该‘蛋白质’之间建立了联系，搭桥项，当选”；A、C、D“不是上述论证的首要前提”。与编者一致。同题见GK2020F-113（已一并锁定）。编者难度估计：中。'),

dict(id='PD3B-019', order=4, topic='解释', key='GD20131-82', ans_page=11,
 stem='据国家权威科研机构研究证实，当前市场上热销的某品牌保健食品并不含有提高人类身体机能、增强个体免疫力的成分。但调查结果表明，不少身体虚弱的人在购买服用了该品牌的保健食品一段时间后，身体素质明显提高。\n以下最有助于解释上述矛盾的一项是：',
 options={'A': '保健食品作用的发挥具有一定的时间滞后性', 'B': '许多身体健康的人在服用保健食品后体质也增强了', 'C': '购买该品牌保健品的人大多经济条件较好', 'D': '服用保健品的人在生活其他方面也开始注重健康'},
 src='D', chk='D', diff='M',
 sol='矛盾：权威机构证实该保健食品不含提高身体机能、增强免疫力的成分；但不少身体虚弱者服用一段时间后身体素质明显提高。需要：在“产品本身不含有效成分”这一事实不变的前提下，找出体质提高的另一原因。\nA：作用的发挥有滞后性——仍默认产品有效，与“不含有效成分”的已证实事实冲突，不能解释。\nB：许多健康人服后体质也增强——对象换成健康人，且同样没说原因。\nC：购买者大多经济条件较好——经济条件好不能直接说明体质提高，指向不明。\nD：服用者在生活其他方面也开始注重健康——体质提高另有原因（生活方式改变），与“产品无效”并存不悖，当选。\n提速：解释项不能推翻题干已确认的事实，优先找他因。',
 val='解释项不能推翻题干已确认事实（产品不含有效成分），A“滞后性”与事实冲突，D他因成立；广东老卷经典题。',
 flags=['老卷（2013—2016年度）', '扫描件解析出图核对'],
 notes='解析原文（扫描件第11页）：A“说明保健食品还是有功效的，与论据冲突”，D“身体素质明显提高是另有他因，并非是保健食品的功效，很好地解释了矛盾，是答案”。解析把本题称作“加强题型”，属表述问题，答案与编者一致。老卷选用理由：“不能与题干事实冲突”的解释题范例，机制与本日其他解释题不重复。编者难度估计：中。'),

dict(id='PD3B-020', order=5, topic='前提（假设）', key='GD2014X-83', ans_page=18,
 stem='在过去五年中，某地所有家庭所购买衣服的平均价格增长了50%，但在平均家庭消费支出中，购买衣服支出所占比例没发生变化，因此，所有家庭的平均消费支出在这五年中也增长了50%。\n以上结论基于的假设是：',
 options={'A': '在这五年中，所有家庭在购买衣服上的平均花费没有变化', 'B': '在这五年中，所有家庭所购衣服的平均数量没有变化', 'C': '在这五年中，该地的家庭数量增加了50%', 'D': '在这五年中，该地所有家庭用于购买衣服的支出总和增长了50%'},
 src='B', chk='B', diff='H', rate=50, yicuo='D',
 sol='论点：所有家庭的平均消费支出五年中增长了50%。论据：①家庭所购衣服的平均价格增长50%；②平均家庭消费支出中，衣服支出所占比例不变。缺口：平均消费支出＝衣服支出÷占比，占比不变时，总支出增幅＝衣服支出增幅；衣服支出＝平均价格×购买数量，价格涨50%要推出衣服支出涨50%，须假设购买数量不变。\nA：衣服平均花费没有变化——若衣服支出不变、占比不变，总支出也不变，与结论相反，是削弱。\nB：所购衣服平均数量没有变化——数量不变则衣服支出涨50%，占比不变则总支出涨50%；数量一旦变化结论即不成立，B是必要前提，当选。\nC：家庭数量增加50%——结论说的是户均（平均）支出，户数与平均值无关。\nD：全部家庭衣服支出总和增长50%——是总和而非户均；若户数也变，户均衣服支出不一定涨50%，推不出结论，正是易错项。\n程序核验：数量不变时增幅50%；数量降20%时增幅只有20%；户数与支出总和同涨50%时户均衣服支出增幅为0（verify_structure.log）。\n提速：价格、数量、总额、占比混用时，先写等式：支出＝价格×数量，总支出＝分项÷占比。',
 val='价格、数量、支出、占比四个量的关系：须假设购买数量不变；D“支出总和”与“户均”口径不同（正确率50%，易错D）。',
 flags=['老卷（2013—2016年度）', '扫描件解析出图核对'],
 notes='解析原文（扫描件第18页）：“83、正确答案：B，全站正确率：50%，易错项：D。”B“论据所给的是平均价格，即购买衣服的总花费除以衣服数量，要保证结论成立，则需要保证所购买的衣服数量没有变化”；D“‘购买衣服支出总和’与‘家庭平均消费’无关”。与编者一致。老卷选用理由：口径算术型前提，2017年后广东卷同类缺少；正确率50%。编者难度估计：难。'),

dict(id='PD3B-021', order=6, topic='解释', key='JS2023A-96',
 stem='手机APP为了获得一些读取信息和修改手机设置的权限，都会提供用户协议并要求使用者同意。然而，据权威调查显示，大部分使用者很少或从没阅读过APP提供的用户协议，也不乐意APP有超出其功能的某些权限，但他们都会点击“我已阅读并同意用户协议”。\n以下哪项如果为真，最能解释上述现象？',
 options={'A': '如果用户不同意手机APP所提供的用户协议，就不能使用这款APP', 'B': '通过正规平台下载的APP有平台审核其安全性，不需要下载者进行核查', 'C': '很多手机APP的用户协议冗长复杂，用户无法在短时间内读完或读懂', 'D': '对于某些APP来说，用户在使用过程中还能重新设定它获取的各种权限'},
 src='A', chk='A', diff='E',
 sol='矛盾：大部分用户很少或从不阅读用户协议、也不乐意APP拥有超出功能的权限，却都会点击“我已阅读并同意”。需要：一个让他们“不读、不情愿也只能点同意”的原因。\nA：不同意协议就不能使用这款APP——为了使用只能点同意，同时解释了“没读”和“不情愿”两点，当选。\nB：正规平台已审核安全——最多解释“不读”，解释不了“不乐意却仍同意”，且只限正规平台下载的APP。\nC：协议冗长复杂、读不完读不懂——只解释“没读”，没解释“不乐意也同意”。\nD：“某些”APP使用中能重设权限——范围有限，只能部分解释为何敢点同意。\n提速：矛盾里有两个“不”（不读、不乐意）时，选能同时覆盖两点的那项。',
 val='矛盾含“不读”“不乐意”两点，A“不同意就不能用”同时覆盖，B、C只解释“不读”。',
 flags=[],
 notes='解析原文（第53页）：“【答案】A……用户下载app就是为了使用它，因此为了达到目的用户依然会点击同意”。与编者一致。索引切题把后一组（97～98题）的共用题干并入本题D项，已按原页删去。xingce 版文件（文件名未标回忆版）。编者难度估计：易（组内节奏题）。'),

dict(id='PD3B-022', order=7, topic='前提（假设）', key='GDXD2019SW-7',
 stem='如果旅行车程超过3小时，选择自驾游的游客数量就会大大减少。目前，从乙市驾车前往甲市至少需要5小时。如果开通甲、乙两市间的高速公路，从乙市前往甲市的自驾游游客将会显著增加。\n上述论证最可能基于的潜在假设是（　）。',
 options={'A': '该高速公路能够在短时间内开通使用', 'B': '绝大多数游客以自驾的方式前往甲市', 'C': '该高速公路开通后，两市车程将小于3小时', 'D': '很多乙市居民喜欢前往周边城市旅游'},
 src='C', chk='C', diff='M',
 sol='论点：开通甲乙两市间高速公路后，从乙市前往甲市的自驾游游客将显著增加。论据：车程超过3小时，自驾游游客就会大大减少；目前至少需5小时。缺口：要让“超过3小时就大大减少”这一阻碍消失，开通后的车程必须降到3小时以内，否则仍在“大大减少”的区间。\nA：高速能在短时间内开通——论点是“如果开通”的条件句，开通快慢与结论无关。\nB：绝大多数游客以自驾方式前往甲市——讲现有游客的出行方式，与开通后自驾游客是否增加无关。\nC：开通后车程小于3小时——补上数字门槛；若仍超过3小时，自驾游客依旧大大减少，论证不成立，当选。\nD：很多乙市居民喜欢去周边城市旅游——话题无关。\n提速：论据有数字门槛时，前提往往是“新情况跨过了这个门槛”。',
 val='论据给出“超过3小时”门槛，前提是新车程跨过门槛（小于3小时），练数字门槛型前提。',
 flags=[],
 notes='解析原文（第2页）：C“高速公路开通后车程小于3小时，是从乙市前往甲市的自驾游游客增多的必要条件，是论证成立的假设，当选”。与编者一致。编者难度估计：中。'),

dict(id='PD3B-023', order=8, topic='解释', key='GK2015D-107',
 stem='有一段时间，电视机生产行业竞争激烈。由于电视机品牌众多，产品质量成为消费者考虑的首要因素。某电视机生产厂家为了扩大市场份额，一方面加大研发力度，进一步提高了电视机产品的质量；另一方面在价格上作调整，适当降低了产品的价格。然而，调整之后的头三个月，其电视机产品的市场份额不但没有提高反而有所下降。\n以下哪项如果为真，最能解释上述现象：',
 options={'A': '消费者通常会考虑不同产品的价格差异，而非同一产品在不同时期的价格差异', 'B': '一个家庭再次购买电视机产品时会首先考虑原来的品牌', 'C': '消费者通常是通过价格来衡量电视机产品质量的', 'D': '其他电视机生产厂家也调整了产品价格'},
 src='C', chk='C', diff='H',
 sol='矛盾：质量是消费者首要考虑因素；厂家提高了质量又适当降价，三个月后市场份额不升反降。需要：一个让“提质＋降价”反而减少销量的机制。\nA：消费者比较的是不同产品的价格差异——只能说明降价吸引力有限，解释“没增加”，解释不了“下降”。\nB：再次购买时首先考虑原品牌——只能说明份额难改变，同样解释不了下降。\nC：消费者通常通过价格来衡量电视机质量——降价让消费者以为质量变差，而质量正是首要因素，于是份额下降；同时解释了“提质无效”和“降价适得其反”，当选。\nD：其他厂家也调整了价格——调整方向不明，即便同样降价也只能抵消降价优势，解释不了份额下降。\n提速：结果比“没效果”更坏（反而下降）时，要找能让措施起反作用的机制；A、B、D只能解释“没起作用”。',
 val='提质降价后份额不升反降，须找让措施起反作用的机制（以价格衡量质量）；A、B、D只能解释“没增加”。',
 flags=['老卷（2013—2016年度）'],
 notes='解析原文（第12页）：“A、D两项可以解释销量不增，但是没有明确的促使销量下降的原因，而C项通过价格衡量质量，价格下降，人们就会认为其质量也会降低……故正确答案为C。”与编者一致。老卷选用理由：“结果比没效果更坏”型解释题，近年国考、广东卷题源中无同类。同题见GK2015F-112（已一并锁定）。编者难度估计：难。'),

dict(id='PD3B-024', order=9, topic='前提', key='HB2022-106',
 stem='伤害感受神经能够对造血干细胞动员进行调控，增强造血干细胞的黏附或迁移，降钙素基因相关肽（CGRP）是伤害感受神经元主要分泌的神经递质分子。研究者发现，给予CGRP可以显著增强造血干细胞动员。CGRP可以直接影响造血干细胞，诱导细胞表面形成CALCRL和RAMP1蛋白形成的二聚体受体，并促进造血干细胞进入血管。研究专家认为，吃辣可以促进造血干细胞动员。\n如果上述结论为真，需要补充的前提是：',
 options={'A': '骨髓神经纤维中高达77%都是伤害感受神经元', 'B': '辛辣食物导致的“辣味”是一种痛觉，会激活伤害感受神经', 'C': '辣的食物能够促进消化液的分泌，增加消化酶的活性，加速胃肠道蠕动', 'D': '造血干细胞会在神经的调控之下，从骨髓释放进入循环，对损失的血细胞进行补充'},
 src='B', chk='B', diff='M',
 sol='论点：吃辣可以促进造血干细胞动员。论据：伤害感受神经调控造血干细胞动员；其分泌的CGRP可显著增强动员。缺口：论据讲“伤害感受神经”，论点讲“吃辣”——须假设吃辣会激活伤害感受神经。\nA：骨髓神经纤维中77%是伤害感受神经元——仍未提到吃辣，连不上。\nB：辣味是一种痛觉，会激活伤害感受神经——吃辣→激活伤害感受神经→CGRP→动员，链条接通，当选。\nC：辣的食物促进消化——讲消化，与造血干细胞无关。\nD：造血干细胞在神经调控下进入循环、补充血细胞——讲动员后的作用，仍未连上吃辣。\n提速：先圈出论点里论据没出现过的词（吃辣），前提就是它与论据关键词的连线；长科技文段不必读懂细节。',
 val='长科技文段中，论点新词“吃辣”与论据“伤害感受神经”之间搭桥，练快速锁定缺失连线。',
 flags=[],
 notes='解析原文（第50页）：B“在‘吃辣’与‘伤害感受神经’之间建立了联系，搭桥项，当选”。与编者一致。题干原卷跨第17—18页。同题见ZJ2022A-103（已一并锁定）。xingce 版文件（文件名未标回忆版）。编者难度估计：中。'),

dict(id='PD3B-025', order=10, topic='解释', key='GD2022X-66',
 stem='某农村合作社购买了两台新型号收割机，这两台机器收割速度快，而且有助于减少收割过程中的粮食损失。但该农村合作社使用这两台收割机以来，其玉米收割总损失率高达10%，较以往反而有所上升。\n以下最能解释这一现象的是：',
 options={'A': '使用收割机后，该农村合作社收割玉米的效率大幅提高', 'B': '两台收割机仅被用于收割部分田地的玉米', 'C': '操作人员培训不到位，操作收割机时常出现失误', 'D': '玉米并不是当地种植的主要粮食作物'},
 src='C', chk='C', diff='M',
 sol='矛盾：新型收割机速度快、有助于减少收割损失；但使用以来玉米收割总损失率高达10%，较以往反而上升。需要：使损失率上升、且与“使用收割机”相连的因素。\nA：收割效率大幅提高——只重复了“速度快”，没有解释损失率为何上升。\nB：只用于收割部分田地——若机器能减少损失，即便只用在部分田地，总损失率也不应上升；B只能解释“降得少”，解释不了“上升”。\nC：操作人员培训不到位、操作时常失误——机器虽好，操作失误造成更多损失，解释了上升，当选。\nD：玉米不是主要粮食作物——与损失率变化无关。\n提速：“好工具反而更差”先看使用环节（人、操作、条件）；“用得少”只能解释“没降多少”。',
 val='好机器反而损失率上升：C操作失误；B“只用于部分田地”只能解释降得少、不能解释上升，练辨别解释方向。',
 flags=[],
 notes='解析原文（第32—33页）：B“即使仅被用于收割部分田地的玉米，该村玉米收割总损失率较以往也不可能有所上升”，C“操作人员的失误是导致……上升的原因，当选”。与编者一致。同题见GD2022Z-64（乡镇卷，已一并锁定）；xingce 网友回忆版与本版逐字一致（标点除外）。编者难度估计：中。'),

dict(id='PD3B-026', order=11, topic='前提', key='GD2021X-66', ans_page=16,
 stem='胼胝体是人类大脑的重要部分，是连接大脑左右半球的主要通道。研究表明，专业打击乐演奏者的大脑中，胼胝体中的纤维比一般人少且更粗壮。因此，练习打击乐能够有效刺激甚至改变大脑结构。\n补充以下选项作为前提，最有助于使上述结论成立的是（　）。',
 options={'A': '专业打击乐演奏者的大脑左右半球与一般人相比也存在差异', 'B': '其他类型乐手的胼胝体纤维也存在与专业打击乐演奏者相似的特征', 'C': '专业打击乐演奏者在练习打击乐之前的胼胝体纤维与一般人并无区别', 'D': '打击乐业余爱好者胼胝体纤维粗细程度介于专业演奏者和普通人之间'},
 src='C', chk='C', diff='M', rate=76, yicuo='D',
 sol='论点：练习打击乐能够有效刺激甚至改变大脑结构。论据：专业打击乐演奏者的胼胝体纤维比一般人少且更粗壮。缺口：论据只是“演奏者与一般人不同”的横向差异，要推出“练习导致改变”，须排除“本来就不同”（先天差异／因果倒置）。\nA：大脑左右半球也存在差异——又一个差异，仍不知是先天还是练习造成，无助于结论。\nB：其他乐手也有类似特征——特征不专属打击乐，若有作用是削弱“练习打击乐”这一具体原因。\nC：练习打击乐之前的胼胝体纤维与一般人并无区别——排除了先天差异，差异出现在练习之后，是“练习改变大脑”的必要前提，当选。\nD：业余爱好者介于专业演奏者与普通人之间——呈程度梯度，有一定支持作用，但仍不能排除“天生具有这种大脑的人更爱练、练得更多”，不是论证所必需，正是易错项。\n提速：横向比较推“做X改变了Y”，前提首选“做X之前没有差别”。',
 val='横截面差异推“练习改变大脑”，必要前提是“练习前无差别”（排除先天差异）；D程度梯度只是弱支持。',
 flags=['县级扫描卷手工录入', '扫描件解析出图核对'],
 notes='2021年县级卷题本为扫描件、不在索引，对照原页（第8页）逐字录入，原页截图见 source_images。解析原文（扫描件第16—17页）：“66、正确答案：C，全站正确率：76%，易错项：D。”C“说明胼胝体纤维是在开始练习打击乐以后开始产生变化的，属于前提”；D定为“无关选项”，编者认为D有弱支持但非必要，定性不同、答案相同。乡镇卷无同题；GD2021X-66 已手工登记。编者难度估计：中。'),

dict(id='PD3B-027', order=12, topic='解释', key='SD2024-93',
 stem='在工作和生活中，人们遇到拿不准的问题总是习惯于请教专家。人们常常认为，某一领域的专家对该领域了解得更多，相关知识更丰富，经验更多，因此，对该领域相关问题的判断比外行更准确，而专家们对自己的判断通常也非常自信。人们（包括专家自己）对于专家的这一信念被一些人称为“专家幻觉”。\n以下哪项如果为真，最能解释上述现象？',
 options={'A': '对那些与人的情感和性格涉及不多或影响不大的领域，专家预测的准确性较强', 'B': '当事件的可预测性低时，专家比一般人更自信，反而降低了专家的预测水平', 'C': '专门知识的拥有量、经验的丰富程度与判断的准确性之间并不存在必然正相关性', 'D': '由于专家在其研究的领域具有较强专业性，人们对专家有一种习惯性信赖'},
 src='C', chk='C', diff='H',
 sol='要解释的现象：人们（包括专家自己）“专家知识多、经验多，所以判断比外行更准”的信念被称为“专家幻觉”——即这个信念为什么是“幻觉”。\nA：在与情感性格涉及不多的领域，专家预测准确性较强——反而支持专家判断更准，不能说明“幻觉”。\nB：事件可预测性低时专家更自信、预测水平反而降低——只覆盖“可预测性低”这一种情形，范围有限，力度弱。\nC：知识量、经验丰富程度与判断准确性之间并无必然正相关——直接说明“知识多、经验多→判断更准”不成立，解释了为什么称之为幻觉，当选。\nD：专家专业性强，人们对其习惯性信赖——解释的是“人们为什么相信专家”，不是“这一信念为什么是幻觉”，是解释错对象的陷阱。\n提速：先确定要解释的到底是哪一句——这里是“幻觉”二字，而不是“人们为何信专家”。',
 val='先确定要解释的对象是“幻觉”而非“人们为何信专家”，D是解释错对象的陷阱。',
 flags=[],
 notes='解析原文（第31—32页“【解析93—正确答案C】”）：“题干矛盾：……认为前面题干的内容是假的”；B“并没有解释为什么前面题干的内容是‘专家幻觉’”，D“指出人们对专家信赖的原因，并没有解释……”。与编者一致。xingce 版文件（文件名未标回忆版）。编者难度估计：难。'),

dict(id='PD3B-028', order=13, topic='前提（隐含前提）', key='JS2020A-93',
 stem='每个“熊孩子”的背后都有一个“熊家长”。这些“熊家长”对“熊孩子”百依百顺，溺爱娇惯，这使得“熊孩子”以自我为中心，缺乏规则意识，容易产生过激的非理性行为。当“熊孩子”有些行为对他人和社会造成伤害时，“熊家长”也会以“他还是个孩子”来护短辩解，要求原谅。\n以下哪项最可能是“熊家长”辩解所隐含的前提？',
 options={'A': '“熊孩子”犯错误不是故意为之', 'B': '只要是孩子就难免犯错', 'C': '“熊孩子”长大后会成为好孩子', 'D': '孩子犯错误应当被原谅'},
 src='D', chk='D', diff='M',
 sol='论点（熊家长的辩解）：孩子伤害了他人和社会，应当原谅。理由：“他还是个孩子”。缺口：从“是孩子”到“应被原谅”，需要“孩子犯错应当被原谅”这一规范性前提。\nA：犯错不是故意为之——辩解的理由是“是孩子”，不是“非故意”；即便非故意，与“该不该原谅”也没连上。\nB：只要是孩子就难免犯错——只说明“会犯错”，没说“犯了错应被原谅”。\nC：长大后会成为好孩子——讲将来，与现在是否应原谅无关。\nD：孩子犯错误应当被原谅——直接把“是孩子”与“要求原谅”连上，当选。\n提速：结论含“应当、要求”等价值判断时，前提往往是一条价值规则：某类情况应当被如何对待。',
 val='价值判断型前提：从“他还是个孩子”到“要求原谅”需要“孩子犯错应被原谅”这一规范，A、B只谈事实。',
 flags=[],
 notes='解析原文（第17页）：D“在‘原谅’和‘孩子’之间搭桥，为搭桥项，是家长辩解的前提，当选”。与编者一致。xingce 版文件（文件名未标回忆版）。编者难度估计：中。'),

dict(id='PD3B-029', order=14, topic='解释', key='GD2023X-59',
 stem='甲市城区过去一直实行车辆限号通行。从去年开始，该市取消了车辆限号通行，一年后全市交通拥堵指数明显下降，平均车速提高了20%，实现了“车辆不限号，交通不拥堵”的双重效益。\n下列选项如果为真，最能解释这一现象的是（　）。',
 options={'A': '甲市城区打造了多个15分钟便民生活圈，居民购物出行更加便利', 'B': '甲市加强了新能源汽车的配套设施建设，新能源汽车销量大幅提高', 'C': '甲市交通线网优化，城区主干道和重点路段交通状况得到明显改善', 'D': '当油价上涨时，为降低出行成本，部分市民会优先选择公共交通出行'},
 src='C', chk='C', diff='M',
 sol='现象：取消车辆限号后，一年后全市交通拥堵指数明显下降、平均车速提高20%。需要：与“不限号”并存、能使全城交通更顺畅的因素。\nA：打造15分钟便民生活圈，购物出行更便利——购物出行便利不等于开车出行减少，也代表不了全城交通状况，解释力弱。\nB：新能源汽车配套加强、销量大增——车可能更多，解释不了拥堵下降。\nC：交通线网优化，主干道和重点路段交通状况明显改善——直接改善全城交通的关键路段，解释了“不限号也不堵”，当选。\nD：油价上涨时部分市民选公共交通——“当……时”只是条件，题干没说油价上涨，且“部分”市民影响有限。\n提速：解释“放开管控反而更好”，找同期发生、作用于同一结果的另一措施。',
 val='取消限号反而不堵，找同期作用于同一结果的另一措施；A“购物出行便利”不等于少开车。',
 flags=[],
 notes='解析原文（第19页“第59题 正确答案是：【C】”）：A“购物出行更加便利不能代表甲市城区整体交通顺畅”，D“取消限号后油价是否上涨不明确”。与编者一致。xingce 网友回忆版与本版逐字一致（标点除外）。编者难度估计：中。'),

dict(id='PD3B-030', order=15, topic='前提（假设）', key='GDXD2020SW-35',
 stem='有研究显示，中国脑卒中（俗称中风）的患者数量正迅速上升，但对于中风防治效果好、费用低的颈动脉内膜剥脱手术（CEA）却尚未得到普及，该研究进而建议要培养大量能够熟练施行CEA手术的医生以应对严峻形势。\n上述论证最可能基于的潜在假设是（　）。',
 options={'A': 'CEA手术的普及能够使患者、医生双赢', 'B': 'CEA手术的难度极高', 'C': 'CEA手术普及的瓶颈在于熟练施行该手术的人才缺乏', 'D': 'CEA手术的尚未普及使脑卒中患者数量上升'},
 src='C', chk='C', diff='M',
 sol='论点（建议）：要培养大量能熟练施行CEA手术的医生，以应对脑卒中患者迅速增多的形势。论据：患者迅速增加；CEA防治效果好、费用低却尚未普及。缺口：从“CEA未普及”到“要培养医生”，须假设未普及的原因在于缺少能熟练施行的医生，否则培养医生解决不了普及问题。\nA：普及能使患者、医生双赢——讲普及的好处，与“培养医生能否解决未普及”无关。\nB：手术难度“极高”——难度高不等于人才缺乏就是普及瓶颈，“极高”也过强。\nC：普及的瓶颈在于熟练施行该手术的人才缺乏——措施正对症结，当选。\nD：未普及使脑卒中患者数量上升——讲患者增加的原因，与建议能否奏效无关。\n提速：建议型论证的前提，先找“措施对准的正是问题的原因”。',
 val='建议型论证的前提“措施对准症结”：未普及的瓶颈在人才；B“难度极高”不是瓶颈且过强。',
 flags=[],
 notes='解析原文（第8页）：C“在CEA手术普及的瓶颈和手术人才缺乏之间建立起联系……是题干论证的潜在假设，当选”。与编者一致。编者难度估计：中。'),

dict(id='PD3B-031', order=16, topic='解释', key='JS2022A-95',
 stem='某企业秉持人才为上的理念，一直致力于专业技术人才队伍建设，十年来，该企业招聘的大部分机械工人来自甲职业技术学院，今年招聘的机械工人总数明显增加，但从该学院招聘的机械工人数量却大幅减少，而且招进来的很多人没有经过职业技术学院系统的学习。\n以下哪项？如果为真，最能解释该企业今年招聘情况的变化。',
 options={'A': '该企业增设了技术培训部门，以培训新招聘的机械工人', 'B': '三年前，该企业的管理层进行了重大重组，决定推广A、I的应用', 'C': '从去年开始，权威的职业技术学院排行榜上，甲学院落后于乙学院', 'D': '很多没有上过职业技术学院的工人很有才华，只是没有机会上学'},
 src='A', chk='A', diff='M',
 sol='需要解释的变化：该企业一向重视专业技术人才，十年来机械工人大多来自甲职业技术学院；今年招聘总数明显增加，但来自甲学院的大幅减少，且很多新人没有经过职业技术学院的系统学习。\nA：企业增设技术培训部门，培训新招的机械工人——企业能自行培训，不再依赖职校的系统学习，于是可以多招、招未经职校培养的人，同时覆盖“总数增、甲院减、未经系统学习者多”，当选。\nB：三年前决定推广AI应用（原卷作“A、I”）——AI若替代人工应当少招而非多招，且发生在三年前，解释不了今年的变化。\nC：排行榜上甲学院落后于乙学院——可解释从甲学院招得少，但解释不了为何招了很多未经职校学习的人。\nD：很多没上过职校的工人很有才华——“有才华”不等于具备专业技术，与企业“致力于专业技术人才”的理念不合，解释力弱。\n提速：多个事实一起变时，选能同时覆盖全部事实的那项；C只覆盖一半。',
 val='多个事实同时变化（总数增、甲院减、未经系统学习者多），A能全部覆盖，C只覆盖一半；原卷“A、I”等照录。',
 flags=['原卷错字照录'],
 notes='解析原文（第30页“95.解析”）：A“这举措代替了甲职业技术学院的培训功能……可以解释，符合”；B“如果AI代替人工，应该减少招聘机械工人的总数”。与编者一致。原卷设问作“以下哪项？如果为真，最能解释该企业今年招聘情况的变化。”（问号位置错置）、B项作“A、I”，均照录。xingce 版文件（文件名未标回忆版）。编者难度估计：中。'),

dict(id='PD3B-032', order=17, topic='前提', key='GK2023D-101',
 stem='深度学习是一系列复杂的算法，使计算机能够识别数据中的模式并作出预测。研究人员利用深度学习技术训练AI系统自动读取视网膜扫描数据，并识别那些在接下来的一年中患心脏病风险较高的人。研究人员认为该项技术有可能彻底改变传统的心脏病筛查方式。\n上述论证的成立须补充以下哪项作为前提？',
 options={'A': '视网膜扫描数据反映的微小血管变化是预测心脏疾病较为灵敏的指标', 'B': '心脏病筛查需要进行复杂且昂贵的超声心动图或心脏磁共振成像检查', 'C': '视网膜扫描相对便宜，并且在许多配镜服务中被使用', 'D': 'AI系统是解开自然界中存在的复杂模式的绝佳工具'},
 src='A', chk='A', diff='M',
 sol='论点：用深度学习读取视网膜扫描数据识别心脏病高风险者的技术，有可能彻底改变传统心脏病筛查方式。论据：AI能自动读取视网膜扫描数据，识别次年患心脏病风险较高的人。缺口：视网膜数据要能可靠预测心脏病，用它做筛查才有根据——须假设视网膜扫描反映的信息是预测心脏病的有效指标。\nA：视网膜扫描反映的微小血管变化是预测心脏疾病较为灵敏的指标——建立“视网膜数据—心脏病风险”的联系，是该技术可用于筛查的必要基础，当选。\nB：传统筛查需要复杂昂贵的检查——说明传统方式有改进空间，是“新方法有优势”的加分项，不是论证成立所必需。\nC：视网膜扫描相对便宜、在配镜中广泛使用——同样是成本、普及上的优势，属加分项。\nD：AI是解开复杂模式的绝佳工具——泛泛夸AI，不涉及视网膜与心脏病的联系。\n提速：前提题里“成本低、方便”通常是加分项；论证根基是“这个指标真能反映目标”。',
 val='区分必要前提与加分项：视网膜指标有效是根基，“传统检查昂贵”“扫描便宜”只是优势。',
 flags=[],
 notes='解析原文（第30—31页）：A“将‘视网膜扫描数据’和‘心脏病筛查’建立了联系，属于搭桥项，当选”；B、C、D均定为“话题不一致”。编者把B、C看作“有一定支持但非必要”的加分项，定性不同、答案相同。同题见GK2023X-101（已一并锁定）。编者难度估计：中。'),

dict(id='PD3B-033', order=18, topic='解释', key='SZ2020SW-79',
 stem='近年来，化妆品消费市场上，国产化妆品的市场占有率显著提升，品牌效应日益凸显。一项关于国产化妆品购买意愿的调查显示，74%的被调查者表示赞成购买国产化妆品。但是当问及这些被调查者是否曾购买国产化妆品自用，却有70%的人表示“没有”。\n如果以下各项为真，最能够解释上述看似矛盾的现象的是（　）。',
 options={'A': '70%的被调查者表示，欧美化妆品的历史更久，品牌更大，更能够引领时尚', 'B': '大部分被调查者在购买自用化妆品时，主要考虑其功效及自身肤况，不太考虑产地', 'C': '购买国产化妆品的消费者中，70%的人将其作为礼物送人，只有30%的人选择自用', 'D': '大部分被调查者表示，会将每年的化妆品消费支出控制在1000元以内'},
 src='C', chk='C', diff='M', rate=71, yicuo='B',
 sol='矛盾：74%的被调查者赞成购买国产化妆品，但问及是否曾购买国产化妆品“自用”，70%表示没有。需要：使“赞成购买”与“没有买来自用”并存的原因。\nA：70%认为欧美化妆品更好——说明偏好欧美，与“赞成购买国产”相冲突，化解不了矛盾。\nB：大部分人买自用化妆品时不太考虑产地——不考虑产地就不会刻意避开国产，解释不了为何七成从未买国产自用，正是易错项。\nC：购买国产化妆品的人中70%用来送礼，只有30%自用——他们赞成并购买了国产，只是买来送人，所以“没有买来自用”，矛盾化解，当选。\nD：每年化妆品支出控制在1000元以内——与是否买国产、是否自用无关。\n提速：抓矛盾中的限定词——“购买”与“购买自用”不是一回事。',
 val='抓“购买”与“购买自用”的口径差：C送礼化解矛盾；B“不考虑产地”解释不了从未买国产自用（易错B）。',
 flags=[],
 notes='解析原文（第16页）：“79、正确答案：C，全站正确率：71%，易错项：B。”与编者一致。原卷D项在下一页。xingce 版文件（文件名未标回忆版）。编者难度估计：中。'),

dict(id='PD3B-034', order=19, topic='前提', key='GD2022X-58',
 stem='某机构对在广州有创业、就业、实习等经历的港澳青年进行调查，结果显示，有留穗发展意愿的港澳青年比例占七成以上；九成港澳青年通过实习了解和认识广州；有超过一半的港澳青年非常看好粤港澳大湾区的发展前景。因此，来广州实习有助于港澳青年获得对粤港澳大湾区的认同感。\n要使上述推论成立，可以补充的前提是：',
 options={'A': '熟悉广州有助于港澳青年更好地适应在广州工作和生活', 'B': '港澳青年的留穗发展意愿是其对粤港澳大湾区具有认同感的重要表现', 'C': '通过实习，港澳青年对粤港澳大湾区发展前景更有信心', 'D': '超过一半的在穗实习港澳青年参与了这项调查'},
 src='B', chk='B', diff='M',
 sol='论点：来广州实习有助于港澳青年获得对粤港澳大湾区的认同感。论据：七成以上有留穗发展意愿，九成通过实习了解广州，过半非常看好大湾区前景。缺口：论据给的是“留穗发展意愿”“看好前景”，论点要的是“认同感”——须把论据中的指标与“认同感”连上。\nA：熟悉广州有助于适应在穗工作生活——解释了为何愿意留穗，只补充论据，未连上“认同感”，力度弱。\nB：留穗发展意愿是对大湾区具有认同感的重要表现——把“留穗意愿”与“认同感”直接连上，搭桥，当选。\nC：通过实习对大湾区前景更有信心——“有信心”不等于“认同感”，仍未连上。\nD：过半在穗实习青年参与了调查——说明样本有一定代表性，只加强论据可靠性，力度不如B。\n提速：先找论点中的新概念（认同感），再找把它与论据指标挂钩的选项。',
 val='论据给“留穗意愿”“看好前景”，论点要“认同感”，练指标与概念搭桥，并比较搭桥项与补充论据项的力度。',
 flags=[],
 notes='解析原文（第27—28页）：B“指出了‘留穗发展意愿’与‘对粤港澳大湾区的认同感’之间的联系，搭桥项”；A、D“加强论据，力度没有B项搭桥强”；C“更有信心不等同于会产生认同感”。与编者一致。xingce 网友回忆版与本版逐字一致（标点除外）。编者难度估计：中。'),

dict(id='PD3B-035', order=20, topic='解释', key='GD2022X-60',
 stem='逻辑思维能力是一个人最重要的能力之一，但大部分学校都没有开设专门培养逻辑思维能力的课程。\n以下选项若为真，最能有效解释上述现象的是：',
 options={'A': '学校内绝大多数课程的设计核心都是提高学生的逻辑思维能力', 'B': '人们的逻辑思维能力往往能随着学识和社会阅历的增长自然提高', 'C': '绝大多数大学设有关于逻辑思维能力的公共选修课程', 'D': '部分教师对于如何培养逻辑思维能力并没有清晰的认识'},
 src='A', chk='A', diff='M',
 sol='矛盾：逻辑思维能力是一个人最重要的能力之一，但大部分学校没有开设专门培养它的课程。需要：说明“重要却不设专门课程”并不矛盾的原因。\nA：学校内绝大多数课程的设计核心都是提高逻辑思维能力——这项能力已在“绝大多数”课程中培养，无须单设课程，直接化解矛盾，当选。\nB：逻辑思维能力“往往”能随学识和社会阅历自然提高——“能自然提高”不等于学校不必培养，且“社会阅历”在学校之外，解释力弱于A。\nC：绝大多数大学设有相关公共选修课——“大学”只是学校的一部分，与“大部分学校没有开设”并不矛盾，也解释不了。\nD：“部分”教师对如何培养没有清晰认识——部分教师解释不了“大部分学校”不开课。\n提速：注意量词——A“绝大多数课程”覆盖最广；B在学校之外，C、D范围对不上。',
 val='量词决定解释力：A“绝大多数课程”已在培养；B“自然提高”不等于学校不必培养，D“部分教师”范围不够。',
 flags=[],
 notes='解析原文（第28—29页）：A“即使不开设专门培养逻辑思维能力的课程，在绝大多数的课程中也能培养到这项能力，因此不需要单独开设课程，当选”；B“能力会自然提高，不代表就没有通过课程来学习的必要性”。与编者一致。xingce 网友回忆版与本版逐字一致（标点除外）。编者难度估计：中。'),
]
for r in G2:
    r['group'] = 'D09-B2'; r['group_title'] = '逻辑·论证B组：前提与解释'
